INSERT INTO `data_sources` VALUES (1,'nasa_power','NASA POWER (climatology)','NASA Langley Research Center','https://power.larc.nasa.gov/docs/services/api/','Public REST API, no key, JSON','Meteorology about 0.5 x 0.625 degrees (MERRA-2); solar about 1 x 1 degree (CERES)','Modelled / satellite-derived, not a ground station. The grid is coarse for mountains: one cell averages peaks and valleys together.','2026-11-15 10:57:28'),(2,'std_atmosphere','Standard-atmosphere pressure estimate','PAMIR TO MARS team','https://en.wikipedia.org/wiki/Barometric_formula','Calculated: P = 101325 x (1 - 2.25577e-5 x h)^5.25588','Depends on the elevation value used','An estimate from elevation only. Real pressure changes with weather and season.','2026-11-15 10:57:28'),(3,'rems','Curiosity REMS (Rover Environmental Monitoring Station)','NASA PDS / Centro de Astrobiologia (CAB)','https://pds.nasa.gov/','NASA Planetary Data System archive; published REMS papers and CAB weather reports','One location: Gale Crater, Mars','A single site on Mars. The air-temperature sensor is affected by heat from the rover. Values stored here are published summary values, not the full archive.','2026-11-15 10:57:28'),(4,'eid','Earth Impact Database','Planetary and Space Science Centre, University of New Brunswick','https://www.unb.ca/passc/ImpactDatabase/','Website',NULL,'Ages of impact structures are given as ranges (Karakul: less than 5 million years).','2026-11-15 10:57:28'),(5,'team','Team interpretation','PAMIR TO MARS team','https://github.com/','Written by the team from the cited literature',NULL,'An interpretation, not a measurement. Always shown with the \"interpretation\" label.','2026-11-15 10:57:28'),(6,'modis','MODIS Land Surface Temperature and NDVI (MOD11A2, MOD13Q1)','NASA LP DAAC','https://appeears.earthdatacloud.nasa.gov/','AppEEARS point sample (Earthdata Login), CSV loaded with scripts/import_csv.php','LST 1 km, NDVI 250 m','Clear-sky only: cloudy days are missing. Not yet loaded unless rows exist in the measurements table.','2026-11-15 10:57:28'),(7,'diviner','LRO Diviner Lunar Radiometer','NASA / UCLA / PDS Geosciences Node','https://pds-geosciences.wustl.edu/missions/lro/diviner.htm','Download from PDS, CSV loaded with scripts/import_csv.php',NULL,'Surface temperature only: the Moon has no air. Not yet loaded unless rows exist in the measurements table.','2026-11-15 10:57:28'),(8,'srtm','SRTM GL1 / Copernicus DEM (elevation)','NASA LP DAAC / ESA Copernicus, via OpenTopography','https://opentopography.org/','OpenTopography API (free key, server side only) or Earthdata Login','About 30 m','Voids and errors on very steep slopes. Used to verify site elevations.','2026-11-15 10:57:28'),(9,'mola','MOLA Mars elevation (Mars Trek)','NASA JPL Solar System Treks','https://trek.nasa.gov/mars/','WMTS map tiles, no login','MOLA hillshade about 463 m','Mars elevation is measured from the Mars areoid (datum), not from a sea level. It cannot be compared directly with Earth elevation.','2026-11-15 10:57:28'),(10,'mcd','Mars Climate Database','LMD / ESA / CNES','https://www-mars.lmd.jussieu.fr/mars/access.html','Web interface (moderate use only)',NULL,'Climate-model output. Its authors give no warranty of validity. Not yet loaded.','2026-11-15 10:57:28'),(11,'gibs','NASA GIBS map tiles','NASA ESDIS','https://www.earthdata.nasa.gov/engage/open-data-services-software/earthdata-developer-portal/gibs-api','WMTS tiles, no key','Blue Marble base map, up to zoom level 8','Base map picture only. No numbers are taken from it.','2026-11-15 10:57:28');
/*!40000 ALTER TABLE `data_sources` ENABLE KEYS */;
