INSERT INTO `locations` VALUES (1,'karakul','Lake Karakul impact structure','earth','site',39.02000,73.45000,3960.0,'above sea level',1,'Endorheic lake inside an impact structure about 52 km across, in the Eastern Pamir. Age less than 5 million years (Earth Impact Database). The structure was identified from space imagery.'),(2,'murghab','Murghab plateau','earth','site',38.17000,73.96000,3650.0,'above sea level',0,'High cold-desert plateau of the Eastern Pamir. Coordinates and elevation still have to be verified against SRTM.'),(3,'akbaital','Ak-Baital pass area','earth','site',38.53000,73.65000,4655.0,'above sea level (to verify with SRTM)',0,'Barren high-altitude terrain on the Pamir Highway. Coordinates and elevation still have to be verified against SRTM.'),(4,'gale','Gale Crater, Mars (Curiosity)','mars','reference',-4.59000,137.44000,-4500.0,'Mars areoid (MOLA datum)',1,'Impact crater about 154 km across, explored by the Curiosity rover since August 2012.'),(5,'lunar_south_pole','Lunar south pole region','moon','reference',-89.50000,0.00000,NULL,'lunar datum',0,'Region planned for a long-term Moon base. No atmosphere: pressure and air temperature cannot be compared with Earth.'),(6,'atacama_yungay','Atacama Desert (Yungay area), Chile','earth','known_analog',-24.09000,-69.92000,NULL,NULL,0,'Hyper-arid desert long used as a Mars analog. Coordinates to verify.'),(7,'ladakh_leh','Ladakh (Leh area), India','earth','known_analog',34.15000,77.58000,NULL,NULL,0,'High-altitude cold desert studied as a Mars analog (Pandey et al. 2019). Coordinates to verify.'),(8,'haughton','Haughton impact structure, Devon Island, Canada','earth','known_analog',75.38000,-89.67000,NULL,NULL,0,'Polar-desert impact structure used for Mars analog missions. Coordinates to verify.'),(9,'mdrs_utah','Mars Desert Research Station, Utah, USA','earth','known_analog',38.41000,-110.79000,NULL,NULL,0,'Mars Society analog research station. Coordinates to verify.'),(10,'grid_n3700_e07250','Grid cell 