INSERT INTO `measurements` VALUES (1,4,1,3,0,730,'measured','Daily mean, first weeks after landing (Aug-Sep 2012)','Daily mean rose from about 730 to 750 Pa; within one sol it swings between about 685 and 780 Pa.','2026-11-15 10:57:28'),(2,4,2,3,0,-33,'measured','One-month average (CAB weather report, Mars Year 33, month 10)','Average ground temperature for a single Martian month. NOT an annual mean: replace with a longer average when available.','2026-11-15 10:57:28'),(3,4,4,5,0,1,'interpretation',NULL,'Gale is an impact crater about 154 km across.','2026-11-15 10:57:28'),(4,5,4,5,0,1,'interpretation',NULL,'Heavily cratered terrain.','2026-11-15 10:57:28'),(5,1,4,4,0,1,'interpretation',NULL,'Karakul: impact structure about 52 km across, age < 5 Ma.','2026-11-15 10:57:28'),(6,3,4,4,0,0,'interpretation',NULL,'No impact structure is listed at this site.','2026-11-15 10:57:28'),(7,2,4,4,0,0,'interpretation',NULL,'No impact structure is listed at this site.','2026-11-15 10:57:28'),(9,8,4,4,0,1,'interpretation',NULL,'Haughton is a confirmed impact structure.','2026-11-15 10:57:28'),(10,1,5,1,0,-6.28,'modelled','25-year Meteorological and Solar Monthly & Annual Climatologies (January 2001 - December 2025)','NASA POWER grid-cell average (cell mean elevation 4442 m).','2026-11-15 11:55:40'),(11,1,2,1,0,-5.13,'modelled','25-year Meteorological and Solar Monthly & Annual Climatologies (January 2001 - December 2025)','NASA POWER grid-cell average (cell mean elevation 4442 m).','2026-11-15 11:55:40'),(12,1,7,1,0,55.27,'modelled','25-year Meteorological and Solar Monthly & Annual Climatologies (January 2001 - December 2025)','NASA POWER grid-cell average (cell mean elevation 4442 m).','2026-11-15 11:55:40'),(13,1,1,1,0,59060,'modelled','25-year Meteorological and Solar Monthly & Annual Climatologies (January 2001 - December 2025)','NASA POWER grid-cell average (cell mean elevation 4442 m).','2026-11-15 11:55:40'),(14,1,3,1,0,4.65,'modelled','25-year Meteorological and Solar Mont