INSERT INTO `parameters` VALUES (1,'pressure','Surface pressure','Pa','log_ratio',3,1,'Compared on a logarithmic scale: a 1000-fold difference gives similarity 0.'),(2,'temp_surface','Mean surface (ground) temperature','°C','abs_kelvin',3,2,'Absolute difference: 100 K apart gives similarity 0.'),(3,'solar','Solar radiation at the surface','kWh/m²/day','relative',2,3,'Relative difference between the two values.'),(4,'crater','Impact-crater geology','yes/no','binary',2,4,'1 if both sites are impact structures or both are not, otherwise 0.'),(5,'temp_air','Mean air temperature (2 m)','°C','none',0,5,'Context only. Used in the analog fingerprint.'),(6,'temp_range','Daily air temperature range','°C','none',0,6,'Monthly maximum minus monthly minimum of 2 m temperature (NASA POWER); annual = mean of 12 months. Larger than a true daily range. Context and fingerprint.'),(7,'humidity','Relative humidity (2 m)','%','none',0,7,'Context and fingerprint.'),(8,'precip','Precipitation','mm/day','none',0,8,'Context and fingerprint.'),(9,'ndvi','Vegetation index (NDVI)','index','none',0,9,'Low values mean bare ground. Context only; Mars has no vegetation.'),(10,'crater_km','Impact-structure diameter','km','none',0,10,'Context only. Used for the crater-to-crater picture.');
